package slice;
import battle.*;
import game.GameSession;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class StatusInterruptionTest {
    static void exhaust(SliceBattle b){int limit=30;while(b.actor()!=null&&limit-->0){BattleResult r=b.actor().hasStatus("rushing")||b.actor().hasStatus("testified")?b.forcedAction():b.defend();if(!r.accepted&&!b.actor().hasStatus("testified"))continue;}assertTrue(limit>0);}
    static void round(SliceBattle b){exhaust(b);b.advancePhase();exhaust(b);b.advancePhase();}
    static void status(BattleEntity e,String id,int duration,String source){BattleEntity.ActiveStatus s=new BattleEntity.ActiveStatus(id,duration,1,"fixture");s.sourceActorId=source;e.addStatus(s);}
    @Test void dotTicksExactlyThreeTimesAndRefreshes(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());BattleEntity p=s.active.get(0);status(p,"stank",3,"enemy");status(p,"stank",3,"enemy");assertEquals(1,p.activeStatuses.size());int hp=p.currentHp;for(int i=0;i<4;i++)round(b);assertEquals(hp-15,p.currentHp);assertFalse(p.hasStatus("stank"));}
    @Test void dotDeathEmitsOnceAndFreezesFinalRound(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());for(BattleEntity e:s.active){e.currentHp=1;status(e,"stank",3,"enemy");status(e,"impression",3,"enemy");}exhaust(b);BattleResult r=b.advancePhase();assertEquals(4,r.facts.stream().filter(f->f.type==BattleResult.Type.DEATH).count());assertEquals(SliceBattle.Outcome.DEFEAT,b.outcome);assertEquals(1,b.groove.current().number);}
    @Test void rushingPaysOneIconAndClears(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());BattleEntity p=b.actor();status(p,"rushing",0,"enemy");assertFalse(b.move(p.basicAttack,b.enemies.get(0)).accepted);BattleResult r=b.forcedAction();assertTrue(r.accepted);assertEquals(3,b.turns.iconCount());assertFalse(p.hasStatus("rushing"));assertSame(s.active.get(1),b.actor());}
    @Test void mutedAllowsBasicButNotSkillsAndExpiresAtTwoPhaseEnds(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());BattleEntity p=b.actor();status(p,"muted",2,"enemy");assertFalse(b.move("modal_motif",b.enemies.get(0)).accepted);assertTrue(b.move(p.basicAttack,b.enemies.get(0)).accepted);round(b);assertTrue(p.hasStatus("muted"));round(b);assertFalse(p.hasStatus("muted"));}
    @Test void zeroMpTestifiedStaysLockedButUnaffordablePaidMoveReleases(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());BattleEntity p=b.actor();status(p,"testified",0,"enemy");p.lockedMoveId=p.basicAttack;p.currentMp=0;assertTrue(b.forcedAction().accepted);assertTrue(p.hasStatus("testified"));exhaust(b);b.advancePhase();exhaust(b);b.advancePhase();p.lockedMoveId="modal_motif";assertFalse(b.forcedAction().accepted);assertFalse(p.hasStatus("testified"));assertEquals(4,b.turns.iconCount());assertTrue(b.defend().accepted);}
    @Test void draggingMovesActorToEndOfNextPhaseOnly(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());status(s.active.get(0),"dragging",0,"enemy");round(b);assertSame(s.active.get(1),b.actor());assertFalse(s.active.get(0).hasStatus("dragging"));round(b);assertSame(s.active.get(0),b.actor());}
    @Test void cueIsReachableAndInterruptsOnceWithFullCommittedCost(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=s.startBattle("1");exhaust(b);b.advancePhase();assertTrue(b.enemyStep().facts.stream().anyMatch(f->f.type==BattleResult.Type.CUE));while(b.actor()!=null)b.enemyStep();b.advancePhase();int pianoMp=s.active.get(0).currentMp,saxMp=s.active.get(1).currentMp;BattleResult r=b.arrange(SliceCombatTest.recipe(b,"blue_note"),b.enemies.get(0),null,null);assertTrue(r.accepted);assertEquals(2,b.turns.iconCount());assertEquals(pianoMp-3,s.active.get(0).currentMp);assertEquals(saxMp-1,s.active.get(1).currentMp);assertEquals(0,r.facts.stream().filter(f->f.type==BattleResult.Type.MOVE).count());assertEquals(0,r.facts.stream().filter(f->f.type==BattleResult.Type.CONTRIBUTION).count());assertFalse(s.discoveries.contains("blue_note"));assertEquals(-4,b.groove.current().score);assertEquals("No interruption cue",b.cueDescription());}
    @Test void killingCueOwnerDisruptsOnce(){GameSession s=new GameSession(ContentBandTest.catalog());SliceBattle b=s.startBattle("1");exhaust(b);b.advancePhase();b.enemyStep();while(b.actor()!=null)b.enemyStep();b.advancePhase();BattleEntity enemy=b.enemies.get(0);enemy.currentHp=1;s.active.get(0).stats.agi=999;BattleResult r=b.move("modal_motif",enemy);assertTrue(r.facts.stream().anyMatch(f->f.type==BattleResult.Type.ENEMY_BAND_DISRUPTED));assertEquals("No interruption cue",b.cueDescription());}
    @Test void reserveCannotActOrReturnSamePhaseAndVoluntaryBreakHasNoPenalty(){GameSession s=new GameSession(ContentBandTest.catalog());s.resolvedEncounters.add("1");s.acquireReward();SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());BattleEntity incoming=s.reserve.get(0);assertTrue(b.swap(1,0).accepted);assertTrue(incoming.waitingForNextPhase);assertFalse(b.swap(1,0).accepted);assertFalse(incoming.canContribute());assertEquals(0,b.groove.current().score);round(b);assertFalse(incoming.waitingForNextPhase);}
    @Test void virtuosoPaysCombinedRolesAndOneBodyGeneratesOneIcon(){GameSession s=new GameSession(ContentBandTest.catalog());BattleEntity v=s.active.get(0);v.race="Virtuoso";v.instrumentIdentities.addAll(Arrays.asList("Piano","Saxophone"));s.active.remove(1);SliceBattle b=SliceCombatTest.battle(s,new SliceCombatTest.FixedRandom());assertEquals(3,b.turns.iconCount());int mp=v.currentMp;assertTrue(b.arrange(SliceCombatTest.recipe(b,"full_chorus"),b.enemies.get(0),null,null).accepted);assertEquals(mp-4,v.currentMp);assertEquals(0,b.turns.iconCount());assertTrue(v.arrangementCommitted);}
}
